for (g = 0; g < NUM_QUBITS; g = g + 1) begin
awg_i_reg[g] <= 16'sh7FFF;
awg_q_reg[g] <= 16'sh0000;
end
end
8'h01: begin
awg_i_reg[current_gate[15:8]] <= cos_table[current_gate[7:0]];
awg_q_reg[current_gate[15:8]] <= sin_table[current_gate[7:0]];
end
8'h02: begin
qubit_ctrl_reg[current_gate[15:8]] <= 1'b1;
qubit_ctrl_reg[current_gate[7:0]] <= 1'b1;
end
default: begin
end
endcase
gate_active <= 1'b1;
if (gate_timer == 1) begin
gate_pc <= gate_pc + 1;
current_gate <= gate_sequence_rom[gate_pc + 1];
gate_timer <= QUBIT_GATE_TIME_NS;
end else begin
gate_timer <= gate_timer - 1;
end
end
end
QS_MEASURE: begin
qubit_ctrl_reg <= {NUM_QUBITS{1'b0}};
gate_active <= 1'b0;
if (gate_timer == 1) begin
quantum_state <= QS_READOUT;
end
gate_timer <= gate_timer - 1;
end
QS_READOUT: begin
measurement_result <= qubit_readout;
quantum_state <= QS_COMPLETE;
end
QS_COMPLETE: begin
quantum_state <= QS_IDLE;
end
