if (!rst_n) begin
photonic_enable_reg <= {PHOTONIC_CHANNELS{1'b0}};
for (g = 0; g < 16; g = g + 1) begin
photonic_accumulator[g] <= 32'd0;
end
end else begin
if (complete_r2 && !complete_r1) begin
for (g = 0; g < PHOTONIC_CHANNELS; g = g + 1) begin
photonic_accumulator[g % 16] <= photonic_accumulator[g % 16] + photonic_power[g];
end
photonic_enable_reg <= {PHOTONIC_CHANNELS{1'b1}};
end else begin
photonic_enable_reg <= {PHOTONIC_CHANNELS{1'b0}};
end
end
end

