reg spin_write_reg;
reg spin_data_reg;
reg [31:0] spintronic_processor [0:15];
reg process_spin;
reg [6:0] spin_counter;

always @(posedge clk_fpga_250mhz or negedge rst_n) begin
if (!rst_n) begin
spin_addr_reg <= 6'd0;
spin_write_reg <= 1'b0;
spin_data_reg <= 1'b0;
process_spin <= 1'b0;
spin_counter <= 7'd0;
for (g = 0; g < 16; g = g + 1) begin
spintronic_processor[g] <= 32'd0;
end
end else begin
if (complete_r2 && !complete_r1 && !process_spin) begin
process_spin <= 1'b1;
spin_counter <= 7'd0;
spin_addr_reg <= 6'd0;
end
if (process_spin) begin
spin_data_reg <= meas_ff2[spin_addr_reg % NUM_QUBITS];
spin_write_reg <= 1'b1;
spintronic_processor[spin_addr_reg[3:0]] <= spintronic_processor[spin_addr_reg[3:0]] + (spin_data_reg ? 32'd1 : 32'd0);
spin_addr_reg <= spin_addr_reg + 1;
spin_counter <= spin_counter + 1;
if (spin_counter == 6'd63) begin
process_spin <= 1'b0;
end
end else begin
spin_write_reg <= 1'b0;
end
end
end

assign spintronic_address = spin_addr_reg;
assign spintronic_write = spin_write_reg;
assign spintronic_data = spin_data_reg;

reg [31:0] hybrid_result [0:15];
reg computation_done_reg;

always @(posedge clk_fpga_250mhz or negedge rst_n) begin
if (!rst_n) begin
for (g = 0; g < 16; g = g + 1) begin
hybrid_result[g] <= 32'd0;
end
computation_done_reg <= 1'b0;
end else begin
if (spin_addr_reg == SPINTRONIC_DOMAINS - 1) begin
for (g = 0; g < 16; g = g + 1) begin
hybrid_result[g] <= classical_data[g] + photonic_accumulator[g] + spintronic_processor[g];
end
computation_done_reg <= 1'b1;
end else begin
computation_done_reg <= 1'b0;
end
end
end

assign hybrid_output = hybrid_result;
assign computation_done = computation_done_reg;

endmodule

